Calls.Text:
JWT’s `exp` claim is a **NumericDate in seconds since the Unix epoch**, while `Date.now()` returns **milliseconds**. Comparing them directly mixes units.

Use either:

```js
const now = Math.floor(Date.now() / 1000);

if (typeof payload.exp !== 'number' || now >= payload.exp) {
  return res.status(401).json({ error: 'Token expired' });
}
```

or:

```js
if (typeof payload.exp !== 'number' || Date.now() >= payload.exp * 1000) {
  return res.status(401).json({ error: 'Token expired' });
}
```

Also ensure you create `exp` in seconds:

```js
const payload = {
  sub: user.id,
  exp: Math.floor(Date.now() / 1000) + 60 * 60 // one hour
};
```

Prefer letting your JWT library verify expiration rather than manually decoding and checking it. With `jsonwebtoken`:

```js
import jwt from 'jsonwebtoken';

function authenticate(req, res, next) {
  const header = req.get('authorization');
  const token = header?.startsWith('Bearer ')
    ? header.slice(7)
    : null;

  if (!token) {
    return res.status(401).json({ error: 'Missing token' });
  }

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET, {
      algorithms: ['HS256']
    });

    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }

    return res.status(401).json({ error: 'Invalid token' });
  }
}
```

`jwt.verify()` validates the signature and checks `exp` automatically. Avoid using `jwt.decode()` for authentication because it does not verify the signature or enforce expiration.

When signing with `jsonwebtoken`, use:

```js
jwt.sign(payload, process.env.JWT_SECRET, {
  algorithm: 'HS256',
  expiresIn: '1h'
});
```

Finally, reject when `now >= exp`, not only when `now > exp`; a token is no longer valid at the exact expiration time.

