```js
// db.js
const { Pool } = require('pg');

function numberFromEnv(name, fallback) {
  const value = Number(process.env[name]);
  return Number.isFinite(value) ? value : fallback;
}

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: numberFromEnv('PG_POOL_MAX', 10),

  // Maximum time to wait while establishing/acquiring a connection
  connectionTimeoutMillis: numberFromEnv(
    'PG_CONNECTION_TIMEOUT_MS',
    5_000
  ),

  // Close unused connections after this period
  idleTimeoutMillis: numberFromEnv('PG_IDLE_TIMEOUT_MS', 30_000),

  // PostgreSQL server-side limit for each SQL statement
  statement_timeout: numberFromEnv('PG_STATEMENT_TIMEOUT_MS', 15_000),

  // Optional client-side query timeout
  query_timeout: numberFromEnv('PG_QUERY_TIMEOUT_MS', 16_000),

  // Prevent connections from living forever; requires a recent pg version
  maxLifetimeSeconds: numberFromEnv('PG_MAX_LIFETIME_SECONDS', 300),

  application_name: process.env.APP_NAME || 'my-node-service',

  // Configure according to your provider. Prefer a verified CA when possible.
  ssl:
    process.env.PGSSL === 'true'
      ? { rejectUnauthorized: true }
      : undefined,
});

// Required: catches failures on idle pooled connections.
pool.on('error', (err) => {
  console.error('Unexpected PostgreSQL pool error', {
    message: err.message,
    code: err.code,
    stack: err.stack,
  });

  // Usually log/alert here rather than immediately exiting.
  // The pool automatically removes the failed idle client.
});

async function query(text, params = []) {
  const startedAt = Date.now();

  try {
    const result = await pool.query(text, params);

    console.debug('PostgreSQL query completed', {
      durationMs: Date.now() - startedAt,
      rowCount: result.rowCount,
    });

    return result;
  } catch (err) {
    console.error('PostgreSQL query failed', {
      durationMs: Date.now() - startedAt,
      message: err.message,
      code: err.code,
      // Avoid logging params if they may contain credentials or PII.
      query: text,
    });

    throw err;
  }
}

async function close() {
  await pool.end();
}

module.exports = { pool, query, close };
```

