  'SELECT id, display_name, created_at FROM users WHERE id = ?',
  [id]
);
```

Also use centralized error middleware that logs the internal error but sends a generic response:

```js
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
});
```

Depending on the data’s sensitivity, consider rate limiting, audit logging, and `Cache-Control: private, no-store` as additional protections.

