Calls.Text:
Use `pg` built-in `Pool`.

```bash
npm install pg
```

```js
// db.js
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: 20,
  min: 2,

  // Fail if connection cannot be acquired/opened in 5 seconds
  connectionTimeoutMillis: 5_000,

  // Close idle connections after 30 seconds
  idleTimeoutMillis: 30_000,

  // Rotate long-lived connections
  maxLifetimeSeconds: 60 * 60,

  // Cancel queries running longer than 10 seconds
  statement_timeout: 10_000,
  query_timeout: 12_000,

  // Needed by some hosted PostgreSQL providers
  ssl:
    process.env.NODE_ENV === 'production'
      ? { rejectUnauthorized: true }
      : false,
});

// Background errors from idle clients.
// Without this listener, pg may emit an unhandled error.
pool.on('error', (error) => {
  console.error('Unexpected PostgreSQL pool error:', error);
});

pool.on('connect', (client) => {
  console.log('PostgreSQL client connected');
});

async function query(text, params) {
  const start = Date.now();

  try {
    return await pool.query(text, params);
  } catch (error) {
    console.error('PostgreSQL query failed', {
      message: error.message,
      code: error.code,
      durationMs: Date.now() - start,
    });
    throw error;
  }
}

async function closePool() {
  await pool.end();
}

module.exports = { pool, query, closePool };
```

Usage:

```js
const db = require('./db');

async function getUser(id) {
  const result = await db.query(
    'SELECT id, email FROM users WHERE id = $1',
    [id]
  );

  return result.rows[0] ?? null;
}
```

Transactions require checked-out client and guaranteed release:

```js
const { pool } = require('./db');

async function transferFunds(fromId, toId, amount) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    await client.query('COMMIT');
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackError) {
      console.error('Rollback failed:', rollbackError);
    }

    throw error;
  } finally {
    client.release();
  }
}
```

Graceful shutdown:

```js
const { closePool } = require('./db');

async function shutdown(signal) {
  console.log(`${signal}: closing PostgreSQL pool`);

  try {
    await closePool();
    process.exit(0);
  } catch (error) {
    console.error('Pool shutdown failed:', error);
    process.exit(1);
  }
}

process.once('SIGTERM', () => shutdown('SIGTERM'));
process.once('SIGINT', () => shutdown('SIGINT'));
```

Key rules:

- Use one process-wide pool, not one pool per request.
- Use parameterized SQL, never string interpolation.
- `pool.query()` automatically checks out and releases client.
- `pool.connect()` requires `client.release()` in `finally`.
- Set `max` based on PostgreSQL connection limit and number of Node.js instances. Example: 5 app instances × `max: 20` = up to 100 connections.
- `connectionTimeoutMillis` covers connection acquisition/opening; `statement_timeout` limits server execution; `query_timeout` limits client-side query waiting.
- For production TLS, use provider CA certificate when possible. Avoid `rejectUnauthorized: false` unless provider explicitly requires it.

