  maxLifetimeSeconds: 60 * 60,

  ssl:
    process.env.NODE_ENV === 'production'
      ? { rejectUnauthorized: true }
      : false,
});

// Handles errors from idle pooled clients.
// Without listener, idle-client errors can crash process.
