```tsx
import React, { ErrorInfo, ReactNode } from "react";

type ErrorBoundaryProps = {
  children: ReactNode;
  fallback?: (error: Error, retry: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
};

type ErrorBoundaryState = {
  error: Error | null;
  retryKey: number;
};

export class ErrorBoundary extends React.Component<
  ErrorBoundaryProps,
  ErrorBoundaryState
> {
  state: ErrorBoundaryState = {
    error: null,
    retryKey: 0,
  };

  static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("React render error", {
      error,
      message: error.message,
      stack: error.stack,
      componentStack: info.componentStack,
    });

    this.props.onError?.(error, info);
  }

  retry = () => {
    this.setState(({ retryKey }) => ({
      error: null,
      retryKey: retryKey + 1,
    }));
  };

  render() {
    const { error, retryKey } = this.state;

    if (error) {
      if (this.props.fallback) {
        return this.props.fallback(error, this.retry);
      }

      return (
        <div role="alert">
          <h2>Something went wrong</h2>
          <p>{error.message}</p>
          <button type="button" onClick={this.retry}>
            Retry
          </button>
        </div>
      );
    }

    // Changing key remounts child tree during retry.
    return <React.Fragment key={retryKey}>{this.props.children}</React.Fragment>;
  }
}
```

Usage:

```tsx
<ErrorBoundary
  onError={(error, info) => {
    errorMonitoringService.captureException(error, {
      extra: { componentStack: info.componentStack },
    });
  }}
  fallback={(error, retry) => (
    <section role="alert">
      <h1>Page unavailable</h1>
      <p>{error.message}</p>
      <button onClick={retry}>Try again</button>
    </section>
  )}
>
  <App />
</ErrorBoundary>
```

Catches descendant render, constructor, and lifecycle errors. Does not catch event-handler, async callback, server-rendering, or boundary’s own errors.

