A common choice is the [`pg`](https://node-postgres.com/) package and its built-in `Pool`.

```bash
npm install pg
```

## Pool configuration

```js
// db.js
import pg from 'pg';
import fs from 'node:fs';

const { Pool } = pg;

const ssl =
  process.env.PGSSL === 'true'
    ? {
        rejectUnauthorized: true,
        // Use your provider's CA certificate when required:
        ca: process.env.PGSSL_CA_FILE
          ? fs.readFileSync(process.env.PGSSL_CA_FILE, 'utf8')
          : undefined,
      }
    : false;

export const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl,

  // Size this according to the database's total connection limit and the
  // number of application instances.
  max: Number(process.env.PG_POOL_MAX ?? 10),

  // Maximum time to wait while obtaining/creating a connection.
  connectionTimeoutMillis: Number(
    process.env.PG_CONNECT_TIMEOUT_MS ?? 5_000,
  ),

  // Close unused clients after this period.
  idleTimeoutMillis: Number(process.env.PG_IDLE_TIMEOUT_MS ?? 30_000),

  // Periodically replace long-lived connections. Supported by recent pg versions.
  maxLifetimeSeconds: Number(process.env.PG_MAX_LIFETIME_SECONDS ?? 300),

  // PostgreSQL server-side limits.
  statement_timeout: Number(process.env.PG_STATEMENT_TIMEOUT_MS ?? 15_000),
  lock_timeout: Number(process.env.PG_LOCK_TIMEOUT_MS ?? 5_000),
  idle_in_transaction_session_timeout: Number(
    process.env.PG_IDLE_TX_TIMEOUT_MS ?? 15_000,
  ),

  // Client-side fallback. Keep this slightly longer than statement_timeout
  // so PostgreSQL normally cancels the query first.
  query_timeout: Number(process.env.PG_QUERY_TIMEOUT_MS ?? 16_000),

  keepAlive: true,
  application_name: process.env.APP_NAME ?? 'node-service',
});

// Required: handles failures occurring on idle pooled clients.
pool.on('error', (error) => {
  console.error('Unexpected PostgreSQL pool client error', {
    message: error.message,
    code: error.code,
    stack: error.stack,
  });

  // Usually do not call process.exit() here. The pool removes the failed
  // client and can create a replacement. Instead, report the failure through
  // logging/monitoring and let readiness checks reflect database availability.
});

export async function verifyDatabaseConnection() {
  try {
    await pool.query('SELECT 1');
    console.log('PostgreSQL connection pool initialized');
  } catch (error) {
    console.error('Unable to connect to PostgreSQL', {
      message: error.message,
      code: error.code,
    });
    await pool.end();
    throw error;
  }
}

let closing;

export function closeDatabasePool() {
  if (!closing) {
    closing = pool.end().then(() => {
      console.log('PostgreSQL connection pool closed');
    });
  }

  return closing;
}
```

Example environment variables:

```env
DATABASE_URL=postgresql://app_user:password@localhost:5432/app_db
PG_POOL_MAX=10
PG_CONNECT_TIMEOUT_MS=5000
PG_IDLE_TIMEOUT_MS=30000
PG_STATEMENT_TIMEOUT_MS=15000
PG_QUERY_TIMEOUT_MS=16000
PG_IDLE_TX_TIMEOUT_MS=15000
PGSSL=false
```

Avoid disabling certificate verification with `rejectUnauthorized: false` in production. Use the CA certificate supplied by your database provider.

## Running regular queries

For individual queries, prefer `pool.query()`. It automatically obtains and releases a client:

```js
import { pool } from './db.js';

export async function findUser(id) {
  try {
    const result = await pool.query(
      'SELECT id, email FROM users WHERE id = $1',
      [id],
    );

    return result.rows[0] ?? null;
  } catch (error) {
    if (error.code === '57014') {
      // PostgreSQL query cancellation, commonly statement_timeout.
      throw new Error('Database query timed out', { cause: error });
    }

    console.error('Database query failed', {
      code: error.code,
      message: error.message,
    });

    throw error;
  }
}
```

Always parameterize values with `$1`, `$2`, etc. rather than constructing SQL through string interpolation.

## Transactions

Transactions require a dedicated client. Always release it in `finally`, and always attempt a rollback after failure:

```js
import { pool } from './db.js';

export async function transferFunds(fromId, toId, amount) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId],
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId],
    );

    await client.query('COMMIT');
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackError) {
      console.error('Transaction rollback failed', rollbackError);
    }

    throw error;
  } finally {
    client.release();
  }
}
```

Do not use `pool.query()` for the individual statements inside a transaction; each call could use a different connection.

## Startup, health checks, and shutdown

Verify the connection before starting the HTTP server:

```js
import express from 'express';
import {
  pool,
  verifyDatabaseConnection,
  closeDatabasePool,
} from './db.js';

const app = express();

await verifyDatabaseConnection();

app.get('/health/live', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/health/ready', async (req, res) => {
  try {
    await pool.query({
      text: 'SELECT 1',
      query_timeout: 2_000,
    });

    res.json({
      status: 'ready',
      pool: {
        total: pool.totalCount,
        idle: pool.idleCount,
        waiting: pool.waitingCount,
      },
    });
  } catch {
    res.status(503).json({ status: 'not ready' });
  }
});

const server = app.listen(process.env.PORT ?? 3000);

async function shutdown(signal) {
  console.log(`Received ${signal}; shutting down`);

  server.close(async (serverError) => {
    try {
      await closeDatabasePool();
      process.exitCode = serverError ? 1 : 0;
    } catch (error) {
      console.error('Database shutdown failed', error);
      process.exitCode = 1;
    }
  });
}

process.once('SIGTERM', () => shutdown('SIGTERM'));
process.once('SIGINT', () => shutdown('SIGINT'));
```

## What the timeout settings cover

- `connectionTimeoutMillis`: How long an operation waits for a pooled connection/new connection.
- `idleTimeoutMillis`: How long an unused connection remains in the pool.
- `statement_timeout`: PostgreSQL server-side execution timeout. This is generally the most important query limit.
- `query_timeout`: Client-side timeout in `pg`; useful as a fallback.
- `lock_timeout`: Limits how long a statement waits to acquire a PostgreSQL lock.
- `idle_in_transaction_session_timeout`: Terminates sessions left idle while a transaction is open.
- `maxLifetimeSeconds`: Recycles connections periodically, which is useful with proxies, failovers, and network infrastructure.

Keep the server-side `statement_timeout` slightly shorter than the client-side `query_timeout`. Also monitor `pool.waitingCount`: a sustained nonzero value can indicate an undersized pool, slow queries, leaked clients, or database saturation. Do not blindly increase `max`; the sum of all pools across every application instance must fit within PostgreSQL’s connection capacity.

