The standard PostgreSQL driver for Node.js is [`pg`](https://www.npmjs.com/package/pg), which includes a connection pool.

```bash
npm install pg
```

### Pool configuration

```js
// db.js
import pg from 'pg';

const { Pool } = pg;

function intEnv(name, fallback) {
  const value = Number.parseInt(process.env[name] ?? '', 10);
  return Number.isFinite(value) ? value : fallback;
}

export const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: intEnv('PG_POOL_MAX', 10),

  // Fail instead of waiting indefinitely for a connection
  connectionTimeoutMillis: intEnv('PG_CONNECT_TIMEOUT_MS', 5_000),

  // Close unused connections after this period
  idleTimeoutMillis: intEnv('PG_IDLE_TIMEOUT_MS', 30_000),

  // Server-side protection against long-running statements
  statement_timeout: intEnv('PG_STATEMENT_TIMEOUT_MS', 15_000),

  // End transactions that remain idle while holding locks
  idle_in_transaction_session_timeout: intEnv(
    'PG_IDLE_TRANSACTION_TIMEOUT_MS',
    30_000,
  ),

  application_name: process.env.SERVICE_NAME ?? 'node-api',

  // Configure this according to your provider's certificate requirements.
  ssl:
    process.env.PG_SSL === 'true'
      ? { rejectUnauthorized: true }
      : undefined,
});

// Handles errors emitted by idle pooled clients. Without this listener,
// an emitted "error" event can terminate the Node.js process.
pool.on('error', (error) => {
  console.error('Unexpected PostgreSQL pool error', {
    message: error.message,
    code: error.code,
  });

  // Report to your monitoring system here. Usually do not exit immediately;
  // individual requests can fail while the database recovers.
});
```

Example environment:

```env
DATABASE_URL=postgresql://app_user:secret@localhost:5432/app_db
PG_POOL_MAX=10
PG_CONNECT_TIMEOUT_MS=5000
PG_IDLE_TIMEOUT_MS=30000
PG_STATEMENT_TIMEOUT_MS=15000
PG_IDLE_TRANSACTION_TIMEOUT_MS=30000
PG_SSL=false
```

### Running ordinary queries

For a single query, use `pool.query()`. It automatically checks out and releases a connection.

```js
export async function getUserById(id) {
  try {
    const result = await pool.query({
      name: 'get-user-by-id',
      text: `
        SELECT id, email, created_at
        FROM users
        WHERE id = $1
      `,
      values: [id],
    });

    return result.rows[0] ?? null;
  } catch (error) {
    if (error.code === '57014') {
      // PostgreSQL query cancellation, commonly statement_timeout
      throw new Error('Database query timed out', { cause: error });
    }

    console.error('Database query failed', {
      code: error.code,
      message: error.message,
      // Avoid logging parameters that may contain sensitive data.
    });

    throw error;
  }
}
```

### Transactions

When checking out a client manually, always release it in `finally`. A transaction must use the same client for every statement.

```js
export async function transferFunds(fromId, toId, amount) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId],
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId],
    );

    await client.query('COMMIT');
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackError) {
      console.error('Transaction rollback failed', rollbackError);
    }

    throw error;
  } finally {
    client.release();
  }
}
```

Do not use `pool.query('BEGIN')`, because subsequent calls may run on different pooled connections.

### Startup check and graceful shutdown

Pools connect lazily, so optionally verify the database during startup:

```js
export async function verifyDatabaseConnection() {
  try {
    await pool.query('SELECT 1');
    console.log('PostgreSQL connection established');
  } catch (error) {
    console.error('PostgreSQL startup check failed', {
      code: error.code,
      message: error.message,
    });
    throw error;
  }
