```

Close the pool during shutdown so the process does not leave open connections:

```js
async function shutdown(signal) {
  console.log(`Received ${signal}; closing PostgreSQL pool`);

  try {
    await pool.end();
    process.exit(0);
  } catch (error) {
    console.error('Failed to close PostgreSQL pool', error);
    process.exit(1);
  }
}

