    const result = await pool.query(
      `UPDATE counters
       SET value = value + 1
       WHERE id = $1
       RETURNING value`,
      [req.params.id]
    );

    if (result.rowCount === 0) {
      return res.status(404).json({ error: 'Counter not found' });
    }

    res.json({ value: result.rows[0].value });
  } catch (err) {
    next(err);
  }
});
```

Concurrent requests will be serialized on that row, so each successful request gets a different returned value.

## If the counter row may not exist

Use an atomic upsert:

```js
const result = await pool.query(
  `INSERT INTO counters (id, value)
   VALUES ($1, 1)
   ON CONFLICT (id)
   DO UPDATE SET value = counters.value + 1
   RETURNING value`,
  [id]
);
```

Ensure `id` has a unique or primary-key constraint:

```sql
CREATE TABLE counters (
  id text PRIMARY KEY,
  value bigint NOT NULL DEFAULT 0
);
```

## If more work must happen with the increment

Use a transaction and keep all transaction queries on the same checked-out client:

```js
const client = await pool.connect();

try {
  await client.query('BEGIN');

  const result = await client.query(
    `UPDATE counters
     SET value = value + 1
     WHERE id = $1
     RETURNING value`,
    [id]
  );

  // Other related database operations using `client`...

  await client.query('COMMIT');
  res.json({ value: result.rows[0].value });
