Use `pg` built-in `Pool`.

```bash
npm install pg
```

```js
// db.js
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: 20,
  min: 2,

  // Fail if no connection becomes available within 5 seconds
  connectionTimeoutMillis: 5_000,

  // Close unused connections after 30 seconds
  idleTimeoutMillis: 30_000,

  // Recycle connections periodically
  maxLifetimeSeconds: 60 * 30,

  // PostgreSQL server-side limits
  statement_timeout: 10_000,
  lock_timeout: 3_000,
  idle_in_transaction_session_timeout: 15_000,

  // node-postgres client-side query timeout
  query_timeout: 12_000,

  keepAlive: true,

  // Enable only when deployment requires TLS.
  // Prefer proper CA verification over rejectUnauthorized: false.
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : false,
});

// Handles errors from idle clients. Without listener, process may crash.
pool.on('error', (error) => {
  console.error('Unexpected idle PostgreSQL client error:', error);
});

pool.on('connect', (client) => {
  client.on('error', (error) => {
    console.error('PostgreSQL client error:', error);
  });
});

async function query(text, params) {
  try {
    return await pool.query(text, params);
  } catch (error) {
    console.error('PostgreSQL query failed', {
      message: error.message,
      code: error.code,
      // Avoid logging params: may contain secrets.
    });
    throw error;
  }
}

async function transaction(callback) {
  const client = await pool.connect();
  let broken = false;

  try {
    await client.query('BEGIN');
    const result = await callback(client);
    await client.query('COMMIT');
    return result;
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackError) {
      broken = true;
      console.error('PostgreSQL rollback failed:', rollbackError);
    }

    throw error;
  } finally {
    // Destroy client instead of returning known-broken connection to pool.
    client.release(broken);
  }
}

async function closePool() {
  await pool.end();
}

module.exports = { pool, query, transaction, closePool };
```

Usage:

```js
const { query, transaction } = require('./db');

async function getUser(id) {
  const result = await query(
    'SELECT id, email FROM users WHERE id = $1',
    [id]
  );

  return result.rows[0] ?? null;
}

async function transfer(fromId, toId, amount) {
  return transaction(async (client) => {
    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );
  });
}
```

Graceful shutdown:

```js
const { closePool } = require('./db');

async function shutdown(signal) {
  console.log(`${signal}: closing PostgreSQL pool`);

  try {
    await closePool();
    process.exit(0);
  } catch (error) {
    console.error('Pool shutdown failed:', error);
    process.exit(1);
  }
}

process.once('SIGTERM', () => shutdown('SIGTERM'));
process.once('SIGINT', () => shutdown('SIGINT'));
```

Timeout roles:

- `connectionTimeoutMillis`: maximum wait for pool connection.
- `idleTimeoutMillis`: removes unused pooled connections.
- `statement_timeout`: PostgreSQL cancels long-running statements.
- `query_timeout`: client stops waiting for query result.
- `lock_timeout`: cancels statements waiting too long for locks.
- `idle_in_transaction_session_timeout`: kills abandoned transactions.

Sizing rule: keep `max × application instances` below PostgreSQL connection budget. Example: 10 app instances with `max: 20` may consume 200 DB connections. Leave capacity for migrations, monitoring, admin access, replicas, and failover. Use PgBouncer when instance count or serverless concurrency makes direct pooling too large.

