Use `pg`:

```bash
npm install pg
```

```js
// db.js
import pg from 'pg';

const { Pool } = pg;

export const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: 10,
  min: 2,
  idleTimeoutMillis: 30_000,
  connectionTimeoutMillis: 5_000,

  // Query timeout on client side
  query_timeout: 10_000,

  // PostgreSQL server-side timeout
  statement_timeout: 10_000,

  // Recycle long-lived connections; requires recent pg version
  maxLifetimeSeconds: 60 * 60,

  ssl:
    process.env.NODE_ENV === 'production'
      ? { rejectUnauthorized: true }
      : false,
});

// Handles errors from idle pooled clients.
// Without listener, idle-client errors can crash process.
pool.on('error', (error) => {
  console.error('Unexpected PostgreSQL pool error:', error);
});

// Optional observability
pool.on('connect', () => {
  console.log('PostgreSQL client connected');
});

export async function query(text, params = []) {
  const startedAt = Date.now();

  try {
    return await pool.query(text, params);
  } catch (error) {
    console.error('PostgreSQL query failed', {
      code: error.code,
      message: error.message,
      durationMs: Date.now() - startedAt,
    });
    throw error;
  }
}

export async function closePool() {
  await pool.end();
}
```

Usage:

```js
import { query } from './db.js';

const result = await query(
  'SELECT id, email FROM users WHERE id = $1',
  [userId],
);
```

For transaction, acquire client and always release:

```js
import { pool } from './db.js';

export async function transferFunds(fromId, toId, amount) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId],
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId],
    );

    await client.query('COMMIT');
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackError) {
      console.error('PostgreSQL rollback failed:', rollbackError);
    }

    throw error;
  } finally {
    client.release();
  }
}
```

Graceful shutdown:

```js
async function shutdown(signal) {
  console.log(`${signal}: closing PostgreSQL pool`);

  try {
    await pool.end();
    process.exit(0);
  } catch (error) {
    console.error('Pool shutdown failed:', error);
    process.exit(1);
  }
}

process.once('SIGTERM', () => shutdown('SIGTERM'));
process.once('SIGINT', () => shutdown('SIGINT'));
```

Environment:

```env
DATABASE_URL=postgresql://app_user:password@db.example.com:5432/app_db
```

Key settings:

- `max`: max concurrent DB connections per Node.js process. Total = `max × process count`; keep below PostgreSQL connection limit.
- `connectionTimeoutMillis`: max wait for connection acquisition/open.
- `idleTimeoutMillis`: close unused connections after interval.
- `query_timeout`: client stops waiting; behavior depends on query/client state.
- `statement_timeout`: PostgreSQL cancels long-running statement. Better protection against runaway queries.
- `maxLifetimeSeconds`: recycle connections, useful with load balancers and managed DB failovers.
- `pool.on('error')`: required for unexpected errors on idle clients.
- `client.release()` in `finally`: prevents pool leaks.
- Parameterized queries: prevent SQL injection.
- TLS: use provider CA when required. Do not use `rejectUnauthorized: false` in production.

Typical starting point: `max: 10`, connection timeout `5s`, idle timeout `30s`, statement timeout `10–30s`. Tune from query latency, workload, process count, and DB connection budget.

