Calls.Text:
Use the `pg` package and configure separate limits for acquiring a connection, executing a statement, and keeping idle clients.

```bash
npm install pg
```

### Pool configuration

```js
// db.js
import pg from 'pg';

const { Pool } = pg;

function envInt(name, defaultValue) {
  const value = Number.parseInt(process.env[name] ?? '', 10);
  return Number.isFinite(value) ? value : defaultValue;
}

export const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Maximum connections opened by this Node.js process.
  max: envInt('PG_POOL_MAX', 10),

  // Maximum time to wait for/establish a pooled connection.
  connectionTimeoutMillis: envInt('PG_CONNECT_TIMEOUT_MS', 5_000),

  // Close clients that remain unused for this long.
  idleTimeoutMillis: envInt('PG_IDLE_TIMEOUT_MS', 30_000),

  // Server-side limit for each SQL statement.
  statement_timeout: envInt('PG_STATEMENT_TIMEOUT_MS', 15_000),

  // Client-side fallback timeout.
  query_timeout: envInt('PG_QUERY_TIMEOUT_MS', 17_000),

  // Prevent abandoned transactions from holding locks indefinitely.
  idle_in_transaction_session_timeout: envInt(
    'PG_IDLE_TRANSACTION_TIMEOUT_MS',
    30_000,
  ),

  keepAlive: true,
  keepAliveInitialDelayMillis: 10_000,

  application_name: process.env.APP_NAME ?? 'node-api',

  // Prefer a CA certificate supplied by your provider.
  ssl: process.env.NODE_ENV === 'production'
    ? {
        rejectUnauthorized: true,
        ...(process.env.PG_CA
          ? { ca: process.env.PG_CA.replace(/\\n/g, '\n') }
          : {}),
      }
    : false,
});

// Required: idle clients can emit background errors.
pool.on('error', (error) => {
  console.error('Unexpected PostgreSQL pool error', {
    message: error.message,
    code: error.code,
    stack: error.stack,
  });

  // Report to monitoring here. Do not automatically terminate for every
  // idle-client error; pg normally removes the failed client from the pool.
});
```

`statement_timeout` should usually be slightly shorter than `query_timeout`, so PostgreSQL cancels the statement before the client gives up waiting.

### Query helper

For individual queries, use `pool.query()`. It automatically acquires and releases the connection.

```js
export async function query(text, values = []) {
  const startedAt = Date.now();

  try {
    return await pool.query({
      text,
      values,
    });
  } catch (error) {
    console.error('PostgreSQL query failed', {
      code: error.code,
      message: error.message,
      durationMs: Date.now() - startedAt,
      // Avoid logging `values`, since they may contain credentials or PII.
    });

    throw error;
  }
}
```

Usage:

```js
import { query } from './db.js';

export async function getUser(id) {
  const result = await query(
    'SELECT id, email FROM users WHERE id = $1',
    [id],
  );

  return result.rows[0] ?? null;
}
```

Always parameterize values rather than constructing SQL strings.

### Transactions

Transactions require a dedicated client. Always release it in `finally`, and roll back on failure.

```js
import { pool } from './db.js';

export async function withTransaction(callback) {
  const client = await pool.connect();
  let destroyClient = false;

  try {
    await client.query('BEGIN');

    const result = await callback(client);

    await client.query('COMMIT');
    return result;
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackError) {
      // The connection may no longer be usable.
      destroyClient = true;

      console.error('PostgreSQL rollback failed', {
        message: rollbackError.message,
        code: rollbackError.code,
      });
    }

    throw error;
  } finally {
    // Passing true removes the connection instead of returning it to the pool.
    client.release(destroyClient);
  }
}
```

Usage:

```js
await withTransaction(async (client) => {
  await client.query(
    'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
    [100, senderId],
  );

  await client.query(
    'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
    [100, recipientId],
  );
});
```

### Graceful shutdown

Stop accepting new requests before closing the pool. `pool.end()` waits for checked-out clients to be returned.

```js
import { pool } from './db.js';

let shuttingDown = false;

export async function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;

  console.log(`Received ${signal}; closing PostgreSQL pool`);

  try {
    // If using Express/Fastify, close the HTTP server before this call.
    await pool.end();
    console.log('PostgreSQL pool closed');
  } catch (error) {
    console.error('Failed to close PostgreSQL pool', error);
    process.exitCode = 1;
  }
}

process.once('SIGTERM', () => void shutdown('SIGTERM'));
process.once('SIGINT', () => void shutdown('SIGINT'));
```

### Timeout and sizing guidelines

- **`connectionTimeoutMillis`**: usually 2–5 seconds. Prevents requests from waiting indefinitely for a connection.
- **`statement_timeout`**: server-side statement limit, often 5–30 seconds depending on the workload.
- **`query_timeout`**: client-side fallback; set it slightly higher than `statement_timeout`.
- **`idleTimeoutMillis`**: typically 10–60 seconds.
- **`idle_in_transaction_session_timeout`**: important for preventing leaked transactions from retaining locks.
- **`max`** applies per Node.js process. With 5 application instances and `max: 10`, the application can open approximately 50 database connections. Leave capacity for migrations, administration, and other services.
- PostgreSQL error code `57014` normally indicates a canceled statement, including `statement_timeout`. Treat it as a timeout and return an appropriate application error.
- Retry only transient failures and only when the operation is safe to repeat. Do not automatically retry arbitrary transactions or non-idempotent writes.

