import React, { ErrorInfo, ReactNode } from "react";

type ErrorBoundaryProps = {
  children: ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
};

type ErrorBoundaryState = {
  error: Error | null;
  retryKey: number;
};

export class ErrorBoundary extends React.Component<
  ErrorBoundaryProps,
  ErrorBoundaryState
> {
  state: ErrorBoundaryState = {
    error: null,
    retryKey: 0,
  };

  static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    // Replace or supplement this with your logging service.
    console.error("Unhandled render error:", {
      error,
      componentStack: info.componentStack,
    });

    this.props.onError?.(error, info);
  }

  private retry = () => {
    this.setState((state) => ({
      error: null,
      retryKey: state.retryKey + 1,
    }));
  };

  render() {
    const { error, retryKey } = this.state;

    if (error) {
      return (
        <div role="alert" style={styles.fallback}>
          <h2>Something went wrong</h2>
          <p>Please try again.</p>

          {process.env.NODE_ENV === "development" && (
            <pre style={styles.details}>{error.message}</pre>
          )}

          <button type="button" onClick={this.retry}>
            Retry
          </button>
        </div>
      );
    }

    // Changing the key remounts the child tree when Retry is clicked.
    return (
      <React.Fragment key={retryKey}>
        {this.props.children}
      </React.Fragment>
    );
  }
}

const styles: Record<string, React.CSSProperties> = {
  fallback: {
    padding: "1rem",
    border: "1px solid #d33",
    borderRadius: "0.5rem",
    background: "#fff5f5",
  },
  details: {
    overflow: "auto",
    whiteSpace: "pre-wrap",
    color: "#b00020",
  },
};
```

Usage:

```tsx
function App() {
  return (
    <ErrorBoundary
      onError={(error, info) => {
        // Example: send to Sentry, Datadog, or another logging service.
        // logger.captureException(error, { componentStack: info.componentStack });
      }}
    >
      <MainApplication />
    </ErrorBoundary>
  );
}
```

Error boundaries catch errors during rendering, constructors, and lifecycle methods in descendant components. They do not catch errors from event handlers, asynchronous callbacks, server-side rendering, or errors thrown by the boundary itself.

