```js
// db.js
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: 20,
  min: 2,

  // Connection lifecycle
  connectionTimeoutMillis: 5_000,
  idleTimeoutMillis: 30_000,
  maxLifetimeSeconds: 60 * 30,

  // Query protection
  statement_timeout: 15_000,
  query_timeout: 20_000,
  lock_timeout: 5_000,

  // Needed by many hosted PostgreSQL providers.
  // Prefer provider CA verification when available.
  ssl:
    process.env.NODE_ENV === 'production'
      ? { rejectUnauthorized: true }
      : false,

  application_name: 'my-node-service',
});

// Handles errors from idle pooled clients.
pool.on('error', (error) => {
  console.error('Unexpected PostgreSQL pool error:', error);
});

// Optional observability.
pool.on('connect', () => {
  console.log('PostgreSQL client connected');
});

async function query(text, params) {
  try {
    return await pool.query(text, params);
  } catch (error) {
    console.error('PostgreSQL query failed', {
      code: error.code,
      message: error.message,
    });
    throw error;
  }
}

async function checkDatabase() {
  const client = await pool.connect();

  try {
    await client.query('SELECT 1');
  } finally {
    client.release();
  }
}

async function closeDatabase() {
  await pool.end();
}

module.exports = {
  pool,
  query,
  checkDatabase,
  closeDatabase,
};
```

If provider requires SSL but does not provide trusted CA configuration, `{ rejectUnauthorized: false }` often works, but disables certificate verification. Prefer provider CA certificate:

```js
ssl: {
  ca: process.env.POSTGRES_CA_CERT,
  rejectUnauthorized: true,
}
```

Application startup and shutdown:

```js
const express = require('express');
const {
  query,
  checkDatabase,
  closeDatabase,
} = require('./db');

const app = express();
let server;

async function start() {
  try {
    await checkDatabase();

    server = app.listen(3000, () => {
      console.log('Server listening on port 3000');
    });
  } catch (error) {
    console.error('Database startup check failed:', error);
    process.exit(1);
  }
}

async function shutdown(signal) {
  console.log(`${signal} received; shutting down`);

  const forceExit = setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10_000);

  forceExit.unref();

  try {
    if (server) {
      await new Promise((resolve, reject) => {
        server.close((error) => {
          if (error) reject(error);
          else resolve();
        });
      });
    }

    await closeDatabase();
    process.exit(0);
  } catch (error) {
    console.error('Graceful shutdown failed:', error);
    process.exit(1);
  }
}

process.once('SIGTERM', () => shutdown('SIGTERM'));
process.once('SIGINT', () => shutdown('SIGINT'));

start();
```

For one query, use `pool.query()`. It checks out and releases client automatically:

```js
const result = await query(
  'SELECT id, email FROM users WHERE id = $1',
  [userId],
);
```

For transactions, manually acquire client and always release in `finally`:

```js
async function transferFunds(fromId, toId, amount) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId],
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId],
    );

    await client.query('COMMIT');
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackError) {
      console.error('Rollback failed:', rollbackError);
    }

    throw error;
  } finally {
    client.release();
  }
}
```

Timeout meanings:

- `connectionTimeoutMillis`: wait limit for obtaining or creating connection.
- `idleTimeoutMillis`: closes unused clients after interval.
- `maxLifetimeSeconds`: rotates old connections; useful with proxies, failovers, credential rotation.
- `statement_timeout`: PostgreSQL cancels statements running too long.
- `query_timeout`: client-side wait limit in `pg`.
- `lock_timeout`: PostgreSQL cancels statements waiting too long for locks.
- `pool.on('error')`: catches background errors from idle clients.
- `pool.end()`: drains and closes pool during shutdown.

Pool sizing matters. Start near `10–20` per application instance, then ensure:

```text
application instances × pool max
```

stays below PostgreSQL connection limit, leaving capacity for migrations, monitoring, and admin access. With many instances, use PgBouncer and smaller Node pools.

