// db.js
const { Pool } = require('pg');

function envInt(name, fallback) {
  const value = Number.parseInt(process.env[name] ?? '', 10);

  if (!Number.isFinite(value) || value < 0) {
    return fallback;
  }

  return value;
}

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: envInt('PG_POOL_MAX', 10),
  min: envInt('PG_POOL_MIN', 0),

  // Fail if connection cannot be acquired/created in time
  connectionTimeoutMillis: envInt('PG_CONNECT_TIMEOUT_MS', 5_000),

  // Close unused pooled connections
  idleTimeoutMillis: envInt('PG_IDLE_TIMEOUT_MS', 30_000),

  // Client-side query timer
  query_timeout: envInt('PG_QUERY_TIMEOUT_MS', 15_000),

  // PostgreSQL server cancels long-running statement
  statement_timeout: envInt('PG_STATEMENT_TIMEOUT_MS', 10_000),

  // Prevent sessions sitting inside abandoned transactions
  idle_in_transaction_session_timeout: envInt(
    'PG_IDLE_TRANSACTION_TIMEOUT_MS',
    30_000
  ),

  application_name: process.env.PG_APPLICATION_NAME ?? 'node-api',

  // Use only when provider requires TLS.
  // Prefer provider CA instead of rejectUnauthorized: false.
  ssl:
    process.env.PGSSL === 'true'
      ? {
          rejectUnauthorized: true,
          ca: process.env.PGSSL_CA,
        }
      : undefined,
});

// Required: catches errors from idle pooled clients.
pool.on('error', (error) => {
  console.error('Unexpected PostgreSQL pool error', {
    message: error.message,
    code: error.code,
  });
});

async function query(text, params = []) {
  const startedAt = Date.now();

  try {
    return await pool.query(text, params);
  } catch (error) {
    console.error('PostgreSQL query failed', {
      message: error.message,
      code: error.code,
      durationMs: Date.now() - startedAt,
    });

    throw error;
  }
}

async function transaction(callback) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');
    const result = await callback(client);
    await client.query('COMMIT');
    return result;
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackError) {
      console.error('PostgreSQL rollback failed', {
        message: rollbackError.message,
        code: rollbackError.code,
      });
    }

    throw error;
  } finally {
    client.release();
  }
}

async function closePool() {
  await pool.end();
}

module.exports = {
  pool,
  query,
  transaction,
  closePool,
};
```

