```js
// db.js
import pg from 'pg';

const { Pool } = pg;

export const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: 20,
  min: 2, // Supported by recent pg versions
  idleTimeoutMillis: 30_000,
  connectionTimeoutMillis: 5_000,
  maxLifetimeSeconds: 300,

  // Query safeguards
  statement_timeout: 10_000,                 // PostgreSQL-side timeout
  query_timeout: 12_000,                     // Node-side timeout
  lock_timeout: 3_000,
  idle_in_transaction_session_timeout: 15_000,

  application_name: 'my-node-service',

  ssl:
    process.env.NODE_ENV === 'production'
      ? { rejectUnauthorized: true }
      : false,
});

// Required: idle pooled clients can emit errors.
pool.on('error', (error) => {
  console.error('Unexpected PostgreSQL pool error', {
    message: error.message,
    code: error.code,
  });
});

// Optional metrics/logging.
pool.on('connect', () => {
  console.log('PostgreSQL client connected');
});

export async function query(text, values = []) {
  const started = Date.now();

  try {
    return await pool.query({ text, values });
  } catch (error) {
    console.error('PostgreSQL query failed', {
      message: error.message,
      code: error.code,
      durationMs: Date.now() - started,
      // Avoid logging values: may contain secrets.
      text,
    });

    throw error;
  }
}

export async function transaction(callback) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');
    const result = await callback(client);
    await client.query('COMMIT');
    return result;
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackError) {
      // Broken connection: remove it instead of returning it to pool.
      client.release(true);
      console.error('PostgreSQL rollback failed', {
        message: rollbackError.message,
        code: rollbackError.code,
      });
      throw error;
    }

    throw error;
  } finally {
    // release(true) above already removes client; repeated release may fail.
    if (!client.released) client.release();
  }
}
```

Safer transaction helper avoiding reliance on internal `released` state:

```js
export async function transaction(callback) {
  const client = await pool.connect();
  let removeClient = false;

  try {
    await client.query('BEGIN');
    const result = await callback(client);
    await client.query('COMMIT');
    return result;
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackError) {
      removeClient = true;
      console.error('PostgreSQL rollback failed', {
        message: rollbackError.message,
        code: rollbackError.code,
      });
    }

    throw error;
  } finally {
    client.release(removeClient);
  }
}
```

Startup and shutdown:

```js
import { pool } from './db.js';

async function start() {
  await pool.query('SELECT 1'); // Fail fast if DB unavailable.

  const server = app.listen(process.env.PORT ?? 3000);

  async function shutdown(signal) {
    console.log(`${signal}: shutting down`);

    server.close(async () => {
      try {
        await pool.end();
        process.exit(0);
      } catch (error) {
        console.error('Pool shutdown failed', error);
        process.exit(1);
      }
    });
  }

  process.once('SIGTERM', () => shutdown('SIGTERM'));
  process.once('SIGINT', () => shutdown('SIGINT'));
}
```

Key settings:

- `max`: Per-process connection limit. Ensure `instances × workers × max` stays below PostgreSQL connection limit.
- `connectionTimeoutMillis`: Maximum wait when establishing/acquiring connection.
- `idleTimeoutMillis`: Close unused clients.
- `maxLifetimeSeconds`: Rotate long-lived connections; useful with proxies, failover, credential rotation.
- `statement_timeout`: Server cancels long query. Most important query timeout.
- `query_timeout`: Client-side deadline. Keep slightly above `statement_timeout`.
- `lock_timeout`: Stop queries waiting too long for locks.
- `idle_in_transaction_session_timeout`: Kill abandoned transactions.
- `pool.on('error')`: Mandatory for errors from idle clients.
- Always release checked-out clients in `finally`.
- Prefer `pool.query()` for single statements; manually acquire client only for transactions or session state.
- PostgreSQL timeout cancellation usually returns SQLSTATE `57014`.
- Retry only known transient errors such as serialization failure `40001` or deadlock `40P01`; retry whole transaction, with backoff, only when operation is safe to repeat.

