```tsx
import React, { ErrorInfo, ReactNode } from "react";

type ErrorBoundaryProps = {
  children: ReactNode;
  fallback?: (error: Error, retry: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
  onRetry?: () => void;
};

type ErrorBoundaryState = {
  error: Error | null;
};

export class ErrorBoundary extends React.Component<
  ErrorBoundaryProps,
  ErrorBoundaryState
> {
  state: ErrorBoundaryState = {
    error: null,
  };

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("React render error", {
      error,
      componentStack: info.componentStack,
    });

    this.props.onError?.(error, info);
  }

  private retry = () => {
    this.setState({ error: null });
    this.props.onRetry?.();
  };

  render() {
    const { error } = this.state;

    if (error) {
      if (this.props.fallback) {
        return this.props.fallback(error, this.retry);
      }

      return (
        <div role="alert">
          <h2>Something went wrong.</h2>
          <pre>{error.message}</pre>
          <button type="button" onClick={this.retry}>
            Retry
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}
```

Usage:

```tsx
<ErrorBoundary
  onError={(error, info) => {
    // Send to logging service.
    reportError(error, info.componentStack);
  }}
  onRetry={() => {
    // Reset failed data or refetch if needed.
  }}
  fallback={(error, retry) => (
    <section role="alert">
      <p>Page failed to load: {error.message}</p>
      <button type="button" onClick={retry}>
        Try again
      </button>
    </section>
  )}
>
  <App />
</ErrorBoundary>
```

Retry clears boundary state. If child still throws during next render, fallback appears again. Error boundaries catch descendant render, lifecycle, and constructor errors; not event-handler, async callback, or server-side rendering errors.

