    message: error.message,
    stack: error.stack,
    componentStack: info.componentStack,
  });
}

export default function App() {
  return (
    <ErrorBoundary logError={logError}>
      <MainContent />
    </ErrorBoundary>
  );
}
```

Catches descendant errors during rendering, constructors, and lifecycle methods. Does not catch event-handler, async callback, server-rendering, or boundary’s own errors. Handle async/event errors with normal `try/catch` or rejected-promise handling.

